{"i":1,"result":{"status":"fulfilled","value":{"chunk_id":"943744","wall_time_seconds":0.000003911,"exit_code":0,"original_token_count":563,"output":""""Small handlers for zizmor's informational command-line modes."""
from pathlib import Path
import sys
import difflib

VERSION = "zizmor 1.25.2\n"
SHELLS = {"bash", "elvish", "fish", "nushell", "powershell", "zsh"}
BASE = Path(__file__).with_name("cli_completions")


def handle(argv):
    """Return (handled, stdout, stderr, status), or handled=False.

    Call before the main argument parser. It handles only modes that exit
    before auditing; ordinary arguments are left to the caller.
    """
    args = list(argv)
    # Clap validates typed option values before processing its version action.
    if "--completions" in args:
        try:
            ci = args.index("--completions")
            shell_value = args[ci + 1]
        except (ValueError, IndexError):
            shell_value = None
        if shell_value is not None and shell_value not in SHELLS:
            err = (f"error: invalid value '{shell_value}' for '--completions <SHELL>'\n"
                   "  [possible values: bash, elvish, fish, nushell, powershell, zsh]\n")
            near = difflib.get_close_matches(shell_value, sorted(SHELLS), n=1)
            if near:
                err += f"\n  tip: a similar value exists: '{near[0]}'\n"
            err += "\nFor more information, try '--help'.\n"
            return True, "", err, 2
    if "--version" in args or "-V" in args:
        return True, VERSION, "", 0
    if "--help" in args or "-h" in args:
        return False, "", "", 0
    if "--completions" in args:
        try:
            i = args.index("--completions")
            shell = args[i + 1]
        except (ValueError, IndexError):
            return False, "", "", 0
        if shell not in SHELLS:
            return False, "", "", 0
        return True, (BASE / (shell + ".completion")).read_text(), "", 0
    if "--thanks" in args:
        if len(args) != 1:
            return False, "", "", 0
        return True, (BASE / "thanks.txt").read_text(), "", 0
    if "--lsp" in args and len(args) == 1:
        return True, "", "", 0
    return False, "", "", 0


def emit_if_handled(argv):
    handled, out, err, status = handle(argv)
    if handled:
        sys.stdout.write(out)
        sys.stderr.write(err)
        return status
    return None
