{"i":1,"result":{"status":"fulfilled","value":{"chunk_id":"d451ca","wall_time_seconds":0.000004896,"exit_code":0,"original_token_count":3335,"output":""""Output helpers for zizmor-compatible formats."""
import json
import os


def _primary(finding):
    locs = finding.get("locations") or []
    for loc in locs:
        if (loc.get("symbolic") or {}).get("kind") == "Primary":
            return loc
    return locs[-1] if locs else {}


def _where(finding):
    loc = _primary(finding)
    sym = loc.get("symbolic") or {}
    key = sym.get("key") or {}
    local = key.get("Local") or {}
    path = local.get("given_path") or ""
    concrete = loc.get("concrete") or {}
    location = concrete.get("location") or {}
    start = location.get("start_point") or {}
    return path, int(start.get("row", 0)) + 1, sym.get("annotation") or ""


def github(findings):
    out = []
    for f in findings:
        if f.get("ignored"):
            continue
        path, line, annotation = _where(f)
        ident = f.get("ident", "finding")
        desc = f.get("desc", ident)
        msg = os.path.basename(path) + ":" + str(line) + ": " + desc
        if annotation:
            msg += ": " + annotation
        props = []
        if path:
            props.append("file=" + path.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A").replace(":", "%3A").replace(",", "%2C"))
        props += ["line=" + str(line), "title=" + ident]
        level = str((f.get("determinations") or {}).get("severity", "medium")).lower()
        cmd = "error" if level == "high" else "warning" if level == "medium" else "notice"
        out.append("::" + cmd + " " + ",".join(props) + "::" + msg.replace("%", "%25").replace("\r", "%0D").replace("\n", "%0A"))
    return "\n".join(out) + ("\n" if out else "")


def sarif(findings):
    """Render a compact SARIF 2.1.0 report from JSON-v1-shaped findings."""
    rules, results = {}, []
    for f in findings:
        ident = f.get("ident", "finding")
        url, desc = f.get("url", ""), f.get("desc", ident)
        rid = "zizmor/" + ident
        rules.setdefault(rid, {"id": rid, "name": ident, "helpUri": url,
            "help": {"text": desc, "markdown": "`" + ident + "`: " + desc + ("\n\nDocs: <" + url + ">" if url else "")},
            "properties": {"tags": ["security"]}})
        if f.get("ignored"):
            continue
        path, line, annotation = _where(f)
        locs = []
        for item in f.get("locations") or []:
            sym = item.get("symbolic") or {}
            # Hidden spans are used for source suppression but are deliberately
            # omitted from user-facing SARIF locations and code flows.
            if sym.get("kind") == "Hidden":
                continue
            con = item.get("concrete") or {}
            pos = con.get("location") or {}
            start, end = pos.get("start_point") or {}, pos.get("end_point") or {}
            k = (sym.get("key") or {}).get("Local") or {}
            p = k.get("given_path") or path
            a = sym.get("annotation") or ""
            physical = {"artifactLocation": {"uri": p}}
            if pos:
                physical["region"] = {"startLine": int(start.get("row", 0))+1,
                    "startColumn": int(start.get("column", 0))+1,
                    "endLine": int(end.get("row", start.get("row", 0)))+1,
                    "endColumn": int(end.get("column", start.get("column", 0)))+1,
                    "sourceLanguage": "yaml"}
                if con.get("feature") is not None:
                    physical["region"]["snippet"] = {"text": con["feature"]}
            logical = {"logicalLocations": [{"properties": {"symbolic": sym}}], "physicalLocation": physical}
            if a:
                logical["message"] = {"text": a}
            locs.append(logical)
        primary = next((x for x in locs if ((x.get("logicalLocations", [{}])[0].get("properties", {}).get("symbolic") or {}).get("kind") == "Primary")), None)
        if primary is None and locs:
            primary = locs[-1]
        det = f.get("determinations") or {}
        result = {"ruleId": rid, "kind": "fail", "level": "error" if det.get("severity") == "High" else "warning",
            "message": {"text": desc + (": " + annotation if annotation else "")},
            "properties": {"zizmor/confidence": det.get("confidence", "Medium"), "zizmor/persona": det.get("persona", "Regular"), "zizmor/severity": det.get("severity", "Medium")}}
        if primary:
            result["locations"] = [primary]
            result["codeFlows"] = [{"threadFlows": [{"locations": [{"importance": "essential" if x is primary else "important", "location": x} for x in locs]}]}]
        results.append(result)
    return {"$schema": "https://docs.oasis-open.org/sarif/sarif/v2.1.0/os/schemas/sarif-schema-2.1.0.json",
        "runs": [{"invocations": [{"executionSuccessful": True}], "results": results,
                 "tool": {"driver": {"name": "zizmor", "version": "1.25.2", "semanticVersion": "1.25.2",
                    "informationUri": "https://docs.zizmor.sh", "downloadUri": "https://github.com/zizmorcore/zizmor",
                    "rules": list(rules.values())}}}], "version": "2.1.0"}


def format_output(kind, findings):
    if kind == "github":
        return github(findings)
    if kind == "sarif":
        return json.dumps(sarif(findings), indent=2, ensure_ascii=False)
    raise ValueError("unsupported output format: " + kind)
"""Small offline source detector for template injection in Actions run blocks."""
import re


_EXPR = re.compile(r"\$\{\{\s*(.*?)\s*\}\}")
_KNOWN_SAFE = {
    "github.sha", "github.workflow", "github.workflow_ref",
    "github.workflow_sha", "github.run_id", "github.run_number",
    "github.run_attempt", "github.repository", "github.repository_id",
    "github.repository_owner", "github.repository_owner_id",
}


def detect_template_injection(text, persona="regular"):
    """Return ``(line_number, expression)`` for suspicious expansions in run blocks.

    The scanner deliberately works on source lines so callers can attach the
    result to their YAML location representation.  Line numbers are 1-based.
    """
    lines = text.splitlines()
    hits = []
    in_run = False
    run_indent = -1
    content_indent = None
    for i, line in enumerate(lines):
        stripped = line.lstrip()
        indent = len(line) - len(stripped)
        if in_run and stripped and not stripped.startswith("#"):
            if content_indent is None and indent > run_indent:
                content_indent = indent
            elif content_indent is not None and indent < content_indent:
                in_run = False
                content_indent = None
        m = re.match(r"^\s*(?:-\s*)?run\s*:\s*(.*)$", line)
        if m:
            value = m.group(1)
            run_indent = indent
            in_run = value.strip() in ("", "|", ">", "|-", ">-") or value.strip().startswith(("|", ">"))
            content_indent = None
            # Inline scalars and the first content line of block scalars.
            for expr in _EXPR.finditer(value):
                if _suspicious(expr.group(1), persona):
                    hits.append((i + 1, expr.group(1)))
            continue
        if in_run:
            for expr in _EXPR.finditer(line):
                if _suspicious(expr.group(1), persona):
                    hits.append((i + 1, expr.group(1)))
    return hits


def _suspicious(expression, persona):
    expr = expression.strip()
    if persona in ("auditor", "pedantic"):
        return True
    # Regular mode permits values that are generated by the workflow engine
    # and are not controlled by a triggering user.
    return not (expr in _KNOWN_SAFE or expr.startswith("github.sha "))
"""Detect block-scalar ``if`` values with fenced expressions and trailing LF."""
import re


def detect_unsound_condition(text):
    """Return 1-based line numbers for suspect ``if: |`` / ``if: >`` fields."""
    lines = text.splitlines()
    results = []
    for i, line in enumerate(lines):
        m = re.match(r"^(\s*)if\s*:\s*([|>])([+-]?)(?:\s*(?:#.*)?)$", line)
        if not m or "-" in m.group(3):
            continue
        base = len(m.group(1))
        for j in range(i + 1, len(lines)):
            candidate = lines[j]
            if not candidate.strip():
                continue
            indent = len(candidate) - len(candidate.lstrip())
            if indent <= base:
                break
            if "${{" in candidate and "}}" in candidate:
                results.append((i + 1, j + 1))
                break
    return results
"""Small offline detector for zizmor's self-hosted-runner audit."""
import re


def detect_self_hosted(text):
    """Return (line_number, source_line) for runs-on values containing self-hosted.

    The caller owns YAML parsing and finding serialization; line numbers are 1-based.
    This accepts scalar and flow-sequence runner declarations, including quoted values.
    """
    results = []
    lines = text.splitlines()
    in_runs_on = False
    runs_indent = -1
    seq_indent = -1
    for number, line in enumerate(lines, 1):
        stripped = line.strip()
        indent = len(line) - len(line.lstrip())
        if not stripped or stripped.startswith('#'):
            continue
        key = re.match(r'^\s*runs-on\s*:\s*(.*)$', line)
        if key:
            value = key.group(1).split('#', 1)[0].strip()
            if re.search(r'(?<![\w-])self-hosted(?![\w-])', value.strip('"\'')):
                results.append((number, line))
            in_runs_on = value in ('', '|', '>')
            runs_indent = indent
            seq_indent = -1
            continue
        if in_runs_on:
            if indent <= runs_indent:
                in_runs_on = False
            elif re.match(r'^\s*-\s*', line):
                if seq_indent < 0:
                    seq_indent = indent
                item = re.sub(r'^\s*-\s*', '', line).split('#', 1)[0].strip().strip('"\'')
                if item == 'self-hosted':
                    results.append((number, line))
                continue
            else:
                in_runs_on = False
    return results


def findings(text, path, persona='regular'):
    """Build JSON-v1-shaped self-hosted-runner findings for integration.

    This audit is intentionally enabled only for auditor and pedantic personas.
    Source locations are approximate YAML line spans (0-based, end-exclusive).
    """
    if str(persona).lower() not in ('auditor', 'pedantic'):
        return []
    lines = text.splitlines()
    output = []
    for number, source in detect_self_hosted(text):
        indent = len(source) - len(source.lstrip())
        job = None
        # The nearest job key at the same indentation level as sibling jobs.
        for i in range(number - 2, -1, -1):
            candidate = lines[i]
            match = re.match(r'^(\s*)([^#\s][^:]*):\s*(?:#.*)?$', candidate)
            if match and len(match.group(1)) < indent:
                # jobs: is an ancestor marker, not a job name.
                if match.group(2) != 'jobs':
                    job = match.group(2).strip('"\'')
                    break
        route = [{'Key': 'jobs'}]
        if job:
            route.append({'Key': job})
        route.append({'Key': 'runs-on'})
        key = {'Local': {'prefix': None, 'given_path': path}}
        location = {
            'start_point': {'row': number - 1, 'column': indent},
            'end_point': {'row': number - 1, 'column': len(source)},
            'offset_span': {'start': sum(len(x) + 1 for x in lines[:number - 1]) + indent,
                            'end': sum(len(x) + 1 for x in lines[:number - 1]) + len(source)},
        }
        symbolic = {'key': key, 'annotation': 'self-hosted runner used here',
                    'route': {'route': route}, 'feature_kind': 'Normal', 'kind': 'Primary'}
        output.append({
            'ident': 'self-hosted-runner',
            'desc': 'runs on a self-hosted runner',
            'url': 'https://docs.zizmor.sh/audits/#self-hosted-runner',
            'determinations': {'confidence': 'High', 'severity': 'Medium',
                               'persona': 'Auditor' if str(persona).lower() == 'auditor' else 'Pedantic'},
            'locations': [{'symbolic': symbolic,
                           'concrete': {'location': location, 'feature': source, 'comments': []}}],
            'ignored': False,
        })
    return output
"""Lightweight source scanner for unpinned GitHub Actions ``uses`` values."""
import re


_SHA = re.compile(r"^[0-9a-fA-F]{40}$")


def detect_unpinned_uses(text):
    """Return ``(line_number, value)`` pairs for remotely referenced unpinned uses.

    Line numbers are 1-based. Local actions and Docker images are excluded.
    """
    found = []
    for number, line in enumerate(text.splitlines(), 1):
        m = re.match(r"^\s*(?:-\s*)?uses\s*:\s*(.*?)\s*(?:#.*)?$", line)
        if not m:
            continue
        value = m.group(1).strip().strip("\"'")
        if not value or value.startswith("./") or value.startswith("docker://"):
            continue
        if "@" not in value:
            # Remote actions without a ref are invalid/implicitly unpinned too.
            found.append((number, value))
            continue
        ref = value.rsplit("@", 1)[1]
        if not _SHA.fullmatch(ref):
            found.append((number, value))
    return found
